cat > java_obs.yara << 'EOF'
rule JavaObfuscated {
  strings:
    $s1 = "ClassLoader"
    $s2 = "URLClassLoader"
    $s3 = { CA FE BA BE }
  condition:
    all of them
}
EOF

cat > hash_compare.yara << 'EOF'
rule HashCompare {
  condition:
    hash.sha256(0, filesize) contains "0000"
}
EOF

cat > vba_shellcode.yara << 'EOF'
rule VBAShellcode {
  strings:
    $sc1 = { 90 90 90 90 }
    $sc2 = { E8 00 00 00 00 }
    $sc3 = { FF E4 }
  condition:
    any of them
}
EOF

cat > unique_section.yara << 'EOF'
import "pe"
rule UniqueSection {
  condition:
    for any section in pe.sections : ( section.characteristics & pe.SECTION_CNT_CODE )
}
EOF

cat > family_hash.yara << 'EOF'
rule MalFamilyHashes {
  condition:
    hash.md5(0, filesize) == "5d41402abc4b2a76b9719d911017c592" or hash.md5(0, filesize) == "7d793037aeb018f1b0f3b3b9e0e8b1b6"
}
EOF

cat > hex_offset.yara << 'EOF'
rule HexAtOffset {
  strings:
    $hex = { 00 00 00 00 }
  condition:
    $hex at 0x200
}
EOF
